  margin:0 auto 20px;border:1px solid #D9B45B;border-radius:999px;
  background:rgba(255,255,255,.06);color:#D9B45B;font-size:20px;line-height:20px}
.mfp.mfp-xms.mfp-native-generated .xms-eyebrow{margin-bottom:12px;font-size:11px;line-height:16px;font-weight:600;
  letter-spacing:.4em;text-transform:uppercase;color:rgba(255,255,255,.7)}
.mfp.mfp-xms.mfp-native-generated h1.xms-display{margin:0!important;font-family:ui-serif,Georgia,Cambria,'Times New Roman',Times,serif!important;
  font-size:48px!important;line-height:1!important;font-weight:500!important;font-style:italic!important;
  color:#fff!important}
.mfp.mfp-xms.mfp-native-generated .xms-hair{display:flex;align-items:center;justify-content:center;gap:12px;margin:16px 0}
.mfp.mfp-xms.mfp-native-generated .xms-hr{width:40px;height:1px;background:#D9B45B;opacity:.7}
.mfp.mfp-xms.mfp-native-generated .xms-hr-word{font-size:10px;line-height:16px;font-weight:400;letter-spacing:.3em;
