.mfp.mfp-xms.mfp-native-generated .xms-sub{font-family:ui-serif,Georgia,Cambria,'Times New Roman',Times,serif!important;
  font-size:18px;line-height:28px;font-weight:400;font-style:italic;color:rgba(255,255,255,.85)}

/* tagline strip, promo box ---------------------------------------------- */
.mfp.mfp-xms.mfp-native-generated .xms-tagline{display:flex;align-items:center;justify-content:center;gap:12px;padding:14px 0;
  background:#fff;border-left:1px solid var(--xms-border);border-right:1px solid var(--xms-border)}
.mfp.mfp-xms.mfp-native-generated .xms-dot{width:4px;height:4px;border-radius:999px;background:#D9B45B}
.mfp.mfp-xms.mfp-native-generated .xms-tagline-t{font-size:11px;line-height:16px;font-weight:700;letter-spacing:.32em;
  text-transform:uppercase;color:var(--xms-primary)}
.mfp.mfp-xms.mfp-native-generated .xms-promo{border:2px solid var(--xms-primary);background:#fff}
.mfp.mfp-xms.mfp-native-generated .xms-promo-in{padding:24px 32px;text-align:center;border-bottom:1px solid #D4EDE7}
.mfp.mfp-xms.mfp-native-generated .xms-kicker{margin-bottom:4px;font-size:10px;line-height:16px;font-weight:900;
