.mfp.mfp-xms.mfp-native-generated .xms-promo-hr{width:48px;height:1px;margin:0 auto 12px;background:#D9B45B}
.mfp.mfp-xms.mfp-native-generated p.xms-promo-b{margin:0!important;font-size:12px!important;line-height:1.625!important;
