.mfp.mfp-xms.mfp-native-generated .xms-body{padding:24px 24px 16px}
.mfp.mfp-xms.mfp-native-generated .xms-cap{margin:0 0 12px;font-size:11px;line-height:16px;font-weight:900;letter-spacing:.1em;
  text-transform:uppercase;text-align:center;color:var(--xms-primary)}
.mfp.mfp-xms.mfp-native-generated .xms-cap-tight{margin-bottom:8px}
.mfp.mfp-xms.mfp-native-generated .xms-prog{margin-bottom:24px}
