.mfp.mfp-xms.mfp-native-generated .xms-field{display:block;margin:0}
.mfp.mfp-xms.mfp-native-generated .xms-label{display:block;margin:0 0 4px;font-size:10px;line-height:15px;font-weight:700;
  letter-spacing:.05em;text-transform:uppercase;color:#5A7A6F}
.mfp.mfp-xms.mfp-native-generated .xms-chips{margin-bottom:16px}
.mfp.mfp-xms.mfp-native-generated .xms-ta{line-height:0;padding-bottom:7px}

/* megaform sets font-family on label/input/select/textarea with !important, so an authored
   <span> inside a <label> inherits the HOST typeface no matter what the shell root declares.
   Element selectors are (0,3,1) here - above megaform, below every authored class rule - and
   <i> is left alone so Font Awesome keeps its own family. */
.mfp.mfp-xms.mfp-native-generated label,.mfp.mfp-xms.mfp-native-generated span,.mfp.mfp-xms.mfp-native-generated p,.mfp.mfp-xms.mfp-native-generated div,.mfp.mfp-xms.mfp-native-generated ul,.mfp.mfp-xms.mfp-native-generated li,.mfp.mfp-xms.mfp-native-generated h1,.mfp.mfp-xms.mfp-native-generated h2,.mfp.mfp-xms.mfp-native-generated h3,.mfp.mfp-xms.mfp-native-generated button{font-family:inherit!important}
.mfp.mfp-xms.mfp-native-generated .mf-field-label{display:none!important}
/* A wizard's page-break Section renders a visible heading the mock has no room for - it exists to
   split the pages, not to be seen. */
.mfp.mfp-xms.mfp-native-generated .mf-section-break,.mfp.mfp-xms.mfp-native-generated .mf-section-title{display:none!important}
.mfp.mfp-xms.mfp-native-generated .mf-field-group{margin:0!important;width:100%}
.mfp.mfp-xms.mfp-native-generated .mf-form-title,.mfp.mfp-xms.mfp-native-generated .mf-form-description,.mfp.mfp-xms.mfp-native-generated .mf-form-actions{display:none!important}
.mfp.mfp-xms.mfp-native-generated .mf-option-item{margin:0!important}
/* megaform gives every option chip a 36px floor and paints .mf-option-icon as a rounded tile. */
.mfp.mfp-xms.mfp-native-generated .mf-option-group--chips .mf-option-check,
.mfp.mfp-xms.mfp-native-generated .mf-option-group--cards .mf-option-check{display:none!important}
.mfp.mfp-xms.mfp-native-generated .mf-option-group--chips .mf-option-ui{min-height:0!important;height:auto!important}
.mfp.mfp-xms.mfp-native-generated .mf-option-group--cards .mf-option-copy{display:block;width:100%}


.mfp.mfp-xms.mfp-native-generated .mf-input[class],.mfp.mfp-xms.mfp-native-generated .mf-select[class]{width:100%!important;box-sizing:border-box!important;
